77	/**
78	 * Translate a completed OTel span into zero or more cloud SessionEvents.
79	 *
80	 * Returns the events to buffer, or an empty array if the span is not relevant.
81	 * Mutates `state` to track parentId chaining and session.start emission.
82	 *
83	 * @internal Exported for testing.
84	 */
85	export function translateSpan(
86		span: ICompletedSpanData,
87		state: SessionTranslationState,
88		context?: WorkingDirectoryContext,
89	): SessionEvent[] {
90		const operationName = span.attributes[GenAiAttr.OPERATION_NAME] as string | undefined;
91		const events: SessionEvent[] = [];
92	
93		if (operationName === GenAiOperationName.INVOKE_AGENT) {
94			// Extract user message first — needed for session.start summary
95			const userRequest = span.attributes[CopilotChatAttr.USER_REQUEST] as string | undefined;
96	
97			// First invoke_agent span → session.start
98			if (!state.started) {
99				state.started = true;
100				events.push(makeEvent(state, 'session.start', {
101					sessionId: getSessionId(span) ?? generateUuid(),
102					version: 1,
103					producer: 'vscode-copilot-chat',
104					copilotVersion: '1.0.0',
105					startTime: new Date(span.startTime).toISOString(),
106					selectedModel: span.attributes[GenAiAttr.REQUEST_MODEL] as string | undefined,
107					context: {
108						cwd: context?.cwd,
109						repository: context?.repository,
110						hostType: 'github',
111						branch: context?.branch,
112						headCommit: context?.headCommit,
113					},
114				}));
115			}
116	
117			// Emit user.message (matches CLI format)
118			if (userRequest) {
119				events.push(makeEvent(state, 'user.message', {
120					content: truncate(userRequest, MAX_USER_MESSAGE_SIZE),
121					source: 'chat',
122					agentMode: 'interactive',
123				}));
124			}
125	
126			// Extract assistant response + tool requests
127			const assistantText = extractAssistantText(span);
128			const toolRequests = extractToolRequests(span);
129			if (assistantText || toolRequests.length > 0) {
130				events.push(makeEvent(state, 'assistant.message', {
131					messageId: generateUuid(),
132					content: truncate(assistantText ?? '', MAX_ASSISTANT_MESSAGE_SIZE),
133					toolRequests: toolRequests.length > 0 ? toolRequests : undefined,
134				}));
135	
136				// Emit tool.execution_start for each tool request (matches CLI pattern)
137				for (const req of toolRequests) {
138					events.push(makeEvent(state, 'tool.execution_start', {
139						toolCallId: req.toolCallId,
140						toolName: req.name,
141						arguments: req.arguments,
142					}));
143				}
144			}
145		}
146	
147		if (operationName === GenAiOperationName.EXECUTE_TOOL) {
148			const toolName = span.attributes[GenAiAttr.TOOL_NAME] as string | undefined;
149			if (toolName) {
150				const toolCallId = (span.attributes[GenAiAttr.TOOL_CALL_ID] as string | undefined) ?? generateUuid();
151				const resultText = span.attributes['gen_ai.tool.result'] as string | undefined;
152				const success = span.status.code !== 2; // SpanStatusCode.ERROR = 2
153				const truncatedResult = resultText ? truncate(resultText, MAX_TOOL_RESULT_SIZE) : '';
154	
155				// Emit tool.execution_complete (matches CLI format exactly)
156				events.push(makeEvent(state, 'tool.execution_complete', {
157					toolCallId,
158					success,
159					result: success ? {
160						content: truncatedResult,
161						detailedContent: truncatedResult,
162					} : undefined,
163					error: !success ? {
164						message: truncatedResult || 'Tool execution failed',
165						code: 'failure',
166					} : undefined,
167				}));
168			}
169		}
170	
171		// Filter out oversized events
172		return events.filter(event => {
173			const size = estimateEventSize(event);
174			if (size > MAX_EVENT_SIZE) {
175				state.droppedCount++;
176				return false;
177			}
178			return true;
179		});
180	}
