25	/**
26	 * Truncate a string to at most `maxLength` stored characters, appending '...' if truncated.
27	 * The returned value, including the truncation suffix, never exceeds `maxLength`.
28	 * Returns `undefined` for falsy input.
29	 */
30	export function truncateForStore(value: string | undefined, maxLength: number): string | undefined {
31		if (!value) {
32			return undefined;
33		}
34		if (value.length <= maxLength) {
35			return value;
36		}
37		const ellipsis = '...';
38		if (maxLength <= ellipsis.length) {
39			return ellipsis.slice(0, maxLength);
40		}
41		return value.slice(0, maxLength - ellipsis.length).trimEnd() + ellipsis;
42	}
